window.QUIZ_BANK['git-github'] = (window.QUIZ_BANK['git-github']||[]).concat([
{id:3441,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub Actions reusable workflow?',options:['A workflow template in the marketplace','A workflow triggered by workflow_call that can be called from other workflows, enabling DRY pipeline composition','A pre-built action step','A shared runner configuration'],answer:1,explanation:'Reusable workflows use the workflow_call trigger. A caller workflow uses "uses: org/repo/.github/workflows/deploy.yml@main". They accept inputs, secrets can be inherited or explicitly passed.'},
{id:3442,topic:'git-github',difficulty:'intermediate',question:'How do you pass inputs to a reusable workflow?',options:['Via environment variables only','Via the "with" keyword in the calling workflow, matching the "inputs" section defined in the reusable workflow\'s workflow_call trigger','Via workflow_dispatch','Via repository variables'],answer:1,explanation:'Reusable workflow defines: on: workflow_call: inputs: environment: type: string. Caller uses: jobs: deploy: uses: ./.github/workflows/deploy.yml with: environment: staging.'},
{id:3443,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub Actions composite action?',options:['A combination of multiple workflows','An action defined with "using: composite" in action.yml that groups multiple steps into a reusable single action callable with "uses:"','A Docker-based action','A marketplace action bundle'],answer:1,explanation:'Composite actions let you combine multiple steps (run, uses) into one reusable action. action.yml: runs: using: composite, steps: [...]. Called like any action: uses: ./path/to/action.'},
{id:3444,topic:'git-github',difficulty:'advanced',question:'What are the three types of custom GitHub Actions?',options:['YAML, JSON, and Docker','JavaScript action (runs in Node.js), Docker container action (runs in Docker), and composite action (sequences of steps)','Public, private, and shared','Workflow, job, and step actions'],answer:1,explanation:'JavaScript actions use @actions/core and @actions/github packages and run directly on the runner. Docker actions run in a container (any language). Composite actions chain existing steps without writing code.'},
{id:3445,topic:'git-github',difficulty:'intermediate',question:'What does action.yml define in a custom GitHub Action?',options:['The workflow trigger','The action metadata: name, description, inputs, outputs, and the runs configuration specifying the action type and entry point','The runner specifications','The repository settings'],answer:1,explanation:'action.yml: name, description, inputs (name, description, required, default), outputs, and runs (using: node20/docker/composite, main: index.js). Required for any custom action.'},
{id:3446,topic:'git-github',difficulty:'intermediate',question:'What is GitHub Container Registry (GHCR)?',options:['A Docker Hub alternative hosted by GitHub','A container registry at ghcr.io that stores Docker and OCI images, linked to GitHub repositories and organizations','A private npm registry','A GitHub package manager'],answer:1,explanation:'GHCR (ghcr.io) hosts container images tied to GitHub accounts. Push: docker login ghcr.io -u USERNAME --password GITHUB_TOKEN; docker push ghcr.io/owner/image:tag. Images inherit repo visibility settings.'},
{id:3447,topic:'git-github',difficulty:'intermediate',question:'How do you authenticate to GHCR in GitHub Actions?',options:['Use a hardcoded password','Use the GITHUB_TOKEN secret: docker login ghcr.io -u ${{github.actor}} --password-stdin <<< ${{secrets.GITHUB_TOKEN}}','Use SSH keys','Use a personal API key'],answer:1,explanation:'GITHUB_TOKEN is automatically provided in every Actions run with appropriate permissions. Set permissions: packages: write in the workflow. For cross-repo pushes, use a PAT with write:packages scope.'},
{id:3448,topic:'git-github',difficulty:'intermediate',question:'What is GitHub Packages?',options:['A marketplace for Actions','A package registry supporting npm, Maven, Gradle, NuGet, RubyGems, Docker, and more, integrated with GitHub repositories','A binary file storage','A release management tool'],answer:1,explanation:'GitHub Packages hosts packages alongside their source code. Authenticate with GITHUB_TOKEN. Configure registry in .npmrc (npm), pom.xml (Maven), or Gradle build files. Packages are scoped to users or orgs.'},
{id:3449,topic:'git-github',difficulty:'beginner',question:'What is GitHub Dependabot?',options:['A code review bot','An automated tool that monitors dependencies for outdated versions and security vulnerabilities, creating PRs to update them','A testing framework','A CI/CD pipeline'],answer:1,explanation:'Dependabot has two features: version-updates (keeps dependencies current by opening PRs) and security-updates (auto-creates PRs when a CVE is found in a dependency). Configured via .github/dependabot.yml.'},
{id:3450,topic:'git-github',difficulty:'intermediate',question:'What does `.github/dependabot.yml` configure?',options:['GitHub Actions triggers','Dependabot update schedules, package ecosystems, directories, labels, reviewers, and PR limits for automatic dependency updates','Branch protection rules','Repository access'],answer:1,explanation:'dependabot.yml: version: 2; updates: - package-ecosystem: npm; directory: /; schedule: interval: weekly; labels: ["dependencies"]; open-pull-requests-limit: 10.'},
{id:3451,topic:'git-github',difficulty:'intermediate',question:'What is GitHub CodeQL?',options:['A query language for issues','A static analysis engine that treats code as data and runs queries (written in CodeQL query language) to find security vulnerabilities','A code coverage tool','A linting framework'],answer:1,explanation:'CodeQL analyzes code semantically. GitHub\'s default setup runs it automatically on push/PR. Supports: JavaScript, Python, Java, C/C++, C#, Go, Ruby, Swift. Results appear in the Security tab as code scanning alerts.'},
{id:3452,topic:'git-github',difficulty:'intermediate',question:'What is CodeQL default setup vs advanced setup?',options:['They are identical','Default: GitHub manages configuration automatically. Advanced: you create a codeql-analysis.yml workflow giving full control over languages, queries, and schedule.','Advanced is deprecated','Default is not recommended'],answer:1,explanation:'Default setup (repo Settings > Code security > Code scanning) requires zero configuration. Advanced setup: add .github/workflows/codeql-analysis.yml for custom query suites, extended queries, or specific build steps.'},
{id:3453,topic:'git-github',difficulty:'intermediate',question:'What is GitHub secret scanning?',options:['Scans for hardcoded passwords only','Automatically scans commits for known secret patterns (API keys, tokens, credentials) from 100+ providers and alerts repository administrators','A third-party security tool','A branch protection rule'],answer:1,explanation:'GitHub Secret Scanning detects accidentally committed secrets. Push protection blocks pushes containing secrets before they reach the remote. Custom patterns can be added for proprietary tokens.'},
{id:3454,topic:'git-github',difficulty:'intermediate',question:'What is GitHub secret scanning push protection?',options:['Scans pull requests only','Prevents pushes containing detected secrets from reaching GitHub, showing an error and requiring the developer to remove or bypass the secret before pushing','A post-merge scan','A CI check'],answer:1,explanation:'Push protection intercepts secrets at push time (before they are stored). Developer must either remove the secret, use a secret manager, or explicitly bypass (with a reason). Available for public repos and with GHAS.'},
{id:3455,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub Environment?',options:['The OS running GitHub Actions','A named deployment target (staging, production) with protection rules, required reviewers, wait timers, and environment-specific secrets and variables','A runner label','A branch configuration'],answer:1,explanation:'Environments add deployment gates. jobs: deploy: environment: production — if production requires a reviewer, the job pauses until approved. Environment secrets are only exposed to jobs referencing that environment.'},
{id:3456,topic:'git-github',difficulty:'intermediate',question:'What are GitHub Environment protection rules?',options:['Branch protection only','Required reviewers (up to 6 people/teams who must approve), wait timer (delay before job runs), and branch filters (only specific branches can deploy)','Approval workflows','Merge restrictions'],answer:1,explanation:'Protection rules pause deployment jobs: required reviewers must approve before the job runs; wait timer adds a delay (useful for canary monitoring); branch filter restricts which branches can deploy to the environment.'},
{id:3457,topic:'git-github',difficulty:'intermediate',question:'What is the GitHub CLI (`gh`)?',options:['A Git GUI client','A command-line tool for GitHub operations: managing PRs, issues, workflows, releases, gists, and repos directly from the terminal','An alias for git commands','A GitHub web scraper'],answer:1,explanation:'gh enables: gh pr create/review/merge/list, gh issue create/close/list, gh workflow run/view/list, gh release create/upload, gh repo create/clone/fork. Authenticates with gh auth login.'},
{id:3458,topic:'git-github',difficulty:'intermediate',question:'What does `gh pr create --draft` do?',options:['Creates a PR and immediately merges it','Creates a pull request in draft state, signaling it is a work in progress and not ready for review','Creates a PR template','Opens a blank PR'],answer:1,explanation:'Draft PRs in GitHub prevent accidental merges and signal work in progress. gh pr create --draft --title "WIP: feature" --body "Description". Convert to ready: gh pr ready.'},
{id:3459,topic:'git-github',difficulty:'intermediate',question:'What is the difference between GitHub Apps and OAuth Apps?',options:['They are identical','GitHub Apps are installed at the repository/org level with fine-grained permissions and a separate identity; OAuth Apps act as the user and request broad scopes','OAuth is newer','GitHub Apps are deprecated'],answer:1,explanation:'GitHub Apps: fine-grained, installation-level permissions, separate bot identity (app[bot]). OAuth Apps: act as the authenticated user, request scopes, better for user-facing applications. GitHub recommends Apps for integrations.'},
{id:3460,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub webhook?',options:['A UI notification','An HTTP POST callback sent to a configured URL when specific GitHub events occur (push, PR, issue, deployment, etc.)','A CI/CD trigger only','A polling mechanism'],answer:1,explanation:'Webhooks deliver JSON payloads for events. Configure in repo/org Settings > Webhooks. Validate with HMAC-SHA256 signature: GitHub sends X-Hub-Signature-256 header. Used by CI/CD systems, chat bots, and monitoring tools.'},
{id:3461,topic:'git-github',difficulty:'intermediate',question:'How do you validate a GitHub webhook payload?',options:['Check the user-agent header','Compute HMAC-SHA256 of the raw payload using your webhook secret and compare with the X-Hub-Signature-256 header value using a constant-time comparison','Check the IP address','Verify the event type header'],answer:1,explanation:'Use hmac.compare_digest (Python) or crypto.timingSafeEqual (Node.js) for constant-time comparison, preventing timing attacks. Never use string equality. The webhook secret is configured when creating the webhook.'},
{id:3462,topic:'git-github',difficulty:'intermediate',question:'What is a typical GitHub Actions CI/CD pipeline structure?',options:['One job for everything','Separate jobs: test (lint + unit + integration), build (compile + package), deploy-staging (conditional on main branch), deploy-production (requires approval environment)','Only a test job','Build and deploy in one step'],answer:1,explanation:'Best practice: test → build → deploy. Jobs depend on each other: needs: [test, build]. deploy-production needs: [deploy-staging] with environment: production and a required reviewer. Artifacts pass between jobs.'},
{id:3463,topic:'git-github',difficulty:'intermediate',question:'How do you build and push a Docker image to GHCR in GitHub Actions?',options:['Use a hardcoded Dockerfile only','Use docker/build-push-action with registry: ghcr.io, image name from github.repository, and tags using docker/metadata-action for semantic versioning','Push manually after build','Use a shell script only'],answer:1,explanation:'Standard pattern: actions/checkout → docker/login-action (registry: ghcr.io) → docker/metadata-action (for tags/labels) → docker/build-push-action (push: true, tags: ${{steps.meta.outputs.tags}}). Builds and pushes in one step.'},
{id:3464,topic:'git-github',difficulty:'advanced',question:'How do you deploy to Kubernetes from GitHub Actions?',options:['Only via kubectl apply directly','Common patterns: azure/k8s-deploy action, or kubectl apply with kubeconfig stored as a secret, or Helm upgrade with a chart, or ArgoCD GitOps sync','Kubernetes does not support GitHub Actions','Using Docker Compose only'],answer:1,explanation:'Store KUBE_CONFIG as a repo secret. In workflow: echo "${{secrets.KUBE_CONFIG}}" > ~/.kube/config; kubectl apply -f k8s/. Or use Helm: helm upgrade --install release ./chart. ArgoCD GitOps: just push to config repo, ArgoCD syncs automatically.'},
{id:3465,topic:'git-github',difficulty:'intermediate',question:'How do you build a signed Android APK in GitHub Actions?',options:['Android builds cannot be signed in CI','Use setup-java, run Gradle assembleRelease, decode base64 keystore secret to file, and sign with jarsigner or Gradle signing config referencing the decoded keystore','Sign manually only','Use GitHub\'s built-in APK signer'],answer:1,explanation:'Store keystore as base64 secret. In workflow: echo ${{secrets.KEYSTORE}} | base64 -d > keystore.jks; run Gradle with signing properties: ./gradlew assembleRelease -Pandroid.injected.signing.store.file=keystore.jks etc.'},
{id:3466,topic:'git-github',difficulty:'intermediate',question:'How do you build an iOS app in GitHub Actions?',options:['iOS builds require a Mac Pro only','Use a macos-latest runner with Xcode installed, select Xcode version with xcodes/install or xcode-select, then use Fastlane or xcodebuild to build and sign','iOS builds are impossible in CI','Use a Linux runner'],answer:1,explanation:'GitHub provides macos-latest (and macos-13, macos-14) runners with multiple Xcode versions. Use maxim-lobanov/setup-xcode or Fastlane with match for code signing certificates stored in a separate private repo or App Store Connect.'},
{id:3467,topic:'git-github',difficulty:'advanced',question:'What is path filtering in GitHub Actions for monorepos?',options:['Runs all workflows always','Using paths: or paths-ignore: in workflow triggers to only run when specific directories change: on: push: paths: ["packages/api/**"]','Using branch filters only','A paid GitHub feature'],answer:1,explanation:'on: push: paths: ["src/frontend/**"] triggers the workflow only when files under src/frontend/ change. Combine with dorny/paths-filter action for dynamic job filtering within a single workflow run.'},
{id:3468,topic:'git-github',difficulty:'advanced',question:'What is git sparse-checkout?',options:['A shallow clone of commits','A feature enabling checkout of only specific directories/files from a large repository rather than the entire working tree','Cloning without history','A partial commit history'],answer:1,explanation:'git sparse-checkout: git clone --no-checkout repo; git sparse-checkout set path/to/subdir; git checkout main. Cone mode is faster: git sparse-checkout init --cone; git sparse-checkout set frontend. Dramatically reduces local disk usage for monorepos.'},
{id:3469,topic:'git-github',difficulty:'advanced',question:'What is a partial clone with `--filter=blob:none`?',options:['Downloads only binary blobs','Clones without downloading any blob (file content) objects; blobs are fetched lazily on demand (e.g., when you checkout a file or git add a file)','Skips all file contents permanently','A shallow clone'],answer:1,explanation:'git clone --filter=blob:none speeds up initial clone significantly for large repos. Blobs are fetched on-demand during checkout. Combine with sparse-checkout for maximum efficiency: clone + sparse-checkout + filter=blob:none.'},
{id:3470,topic:'git-github',difficulty:'advanced',question:'What is `--filter=tree:0` in a partial clone?',options:['Downloads no tree objects','Downloads only commit objects initially; tree and blob objects are fetched on-demand. Smaller initial clone than filter=blob:none but more lazy fetching during operations.','Skips all history','A treeless clone strategy'],answer:1,explanation:'git clone --filter=tree:0 produces a treeless clone: only commits are downloaded. Tree and blob objects fetch lazily. Faster initial clone than blob:none but more network round trips during git operations.'},
{id:3471,topic:'git-github',difficulty:'advanced',question:'What is GitOps?',options:['Using Git for code only','An operational model where Git repositories are the single source of truth for infrastructure and application state; changes are deployed via automated reconciliation loops','A CI/CD framework','A Git branching strategy'],answer:1,explanation:'GitOps: infrastructure is declared in Git. A reconciler (ArgoCD, Flux) watches the Git repo and applies changes to the cluster automatically. Pull-based model: operator pulls from Git, not CI pushing to cluster.'},
{id:3472,topic:'git-github',difficulty:'advanced',question:'What is ArgoCD and how does it work with GitHub?',options:['A GitHub Actions plugin','A Kubernetes GitOps controller that monitors a Git repo and syncs cluster state to match the desired state defined in the repo; supports Helm, Kustomize, and plain YAML','A deploy key manager','A Docker registry'],answer:1,explanation:'ArgoCD Application points to a Git repo path. On every commit, ArgoCD detects drift and syncs (manually or auto-sync). Image Updater can update image tags in Git automatically when new images are pushed.'},
{id:3473,topic:'git-github',difficulty:'intermediate',question:'What is Flux for GitOps?',options:['A GitHub Actions tool','A CNCF GitOps tool (Flux v2) that uses controllers (source-controller, kustomize-controller, helm-controller) to reconcile Kubernetes state from Git repositories','A monitoring tool','A package manager'],answer:1,explanation:'Flux v2 uses a set of controllers. Source Controller watches Git/Helm repos. Kustomize Controller applies Kustomize overlays. Helm Controller deploys Helm releases. Image Automation Controller updates image tags in Git.'},
{id:3474,topic:'git-github',difficulty:'intermediate',question:'What is git credential helper?',options:['A password manager plugin','A program that stores and retrieves credentials for Git operations, avoiding repeated username/password prompts','A SSH key generator','An OAuth helper'],answer:1,explanation:'git config credential.helper store (plaintext file), osxkeychain (macOS Keychain), manager-core (Git Credential Manager for Windows/Mac/Linux). GCM supports OAuth, browser-based auth, and token caching.'},
{id:3475,topic:'git-github',difficulty:'intermediate',question:'What is the recommended way to authenticate with GitHub over HTTPS?',options:['Username and password','Personal Access Token (PAT) or GitHub CLI token (gh auth login) as the password when cloning/pushing via HTTPS. Password auth was removed in August 2021.','SSH over HTTPS port','OAuth flow every time'],answer:1,explanation:'GitHub removed password auth in August 2021. Use: PAT (Settings > Developer settings > Personal access tokens), gh auth login (stores token via Git Credential Manager), or SSH keys with ssh-keygen -t ed25519.'},
{id:3476,topic:'git-github',difficulty:'intermediate',question:'What is the difference between GitHub Enterprise Server and GitHub Enterprise Cloud?',options:['They are identical','Enterprise Server: self-hosted on your infrastructure with full admin control. Enterprise Cloud: hosted by GitHub on github.com with enterprise features like SAML SSO, audit logs, and policy management.','Enterprise Server is deprecated','Enterprise Cloud is self-hosted'],answer:1,explanation:'GHES runs in your own data center (VMware, AWS, Azure, GCP). GHEC is GitHub.com with additional enterprise controls. GHES requires infrastructure management; GHEC is SaaS. Both support SAML SSO and SCIM provisioning.'},
{id:3477,topic:'git-github',difficulty:'advanced',question:'What is `git maintenance` command?',options:['A cleanup alias','A command that runs a set of background maintenance tasks: prefetch (keeps remote refs fresh), gc (garbage collection), commit-graph (speeds up git log), incremental-repack','Removes stale branches','Defragments the repository'],answer:1,explanation:'git maintenance start schedules background tasks via cron/launchd. Tasks: commit-graph (cached reachability data), incremental-repack (reduces pack file fragmentation), gc (frees unreachable objects). Significantly improves performance for large repos.'},
{id:3478,topic:'git-github',difficulty:'advanced',question:'What is a git commit-graph?',options:['A visualization tool','A binary file that caches commit reachability and generation numbers, making git log, git merge-base, and reachability queries significantly faster for large repos','The DAG structure only','A graph visualization format'],answer:1,explanation:'git commit-graph write builds .git/objects/info/commit-graph. Caches parent info, tree OIDs, and generation numbers. git log --oneline becomes 10x+ faster on repos with millions of commits when commit-graph is present.'},
{id:3479,topic:'git-github',difficulty:'advanced',question:'What is a multi-pack-index (MIDX) in Git?',options:['A multiple remotes index','A single index covering multiple pack files, enabling faster object lookup across all packs without consolidating them into one large pack','A binary diff format','A loose object index'],answer:1,explanation:'git multi-pack-index write creates an MIDX file. Instead of searching each pack\'s index separately, git searches the MIDX in one pass. Part of git maintenance and Scalar optimizations for large monorepos.'},
{id:3480,topic:'git-github',difficulty:'advanced',question:'What is Scalar (formerly VFS for Git)?',options:['A Git GUI client','A tool built on top of Git that combines partial clone, sparse-checkout, commit-graph, multi-pack-index, and maintenance for optimal performance with very large repositories','A GitHub Enterprise feature only','A Windows-only tool'],answer:1,explanation:'Scalar scalar clone <url> applies all performance optimizations automatically: partial clone (filter=blob:none), sparse-checkout (cone mode), commit-graph, MIDX, maintenance scheduling. Originally developed by Microsoft for the Windows monorepo.'},
{id:3481,topic:'git-github',difficulty:'intermediate',question:'What is GitHub Advanced Security (GHAS)?',options:['An enterprise firewall','A set of security features: code scanning (CodeQL), secret scanning with push protection, dependency review, and security overview dashboards for organizations','An access control system','A paid GitHub plan'],answer:1,explanation:'GHAS is included free for public repos. For private repos, it requires GHAS license (part of GitHub Enterprise or an add-on). Features: code scanning, secret scanning push protection, Dependabot, dependency review in PRs.'},
{id:3482,topic:'git-github',difficulty:'intermediate',question:'What is dependency review in GitHub?',options:['Manual review of dependencies','A GitHub Actions workflow (actions/dependency-review-action) that blocks PRs adding dependencies with known vulnerabilities by comparing base vs head dependency manifests','A Dependabot feature','A SCA tool'],answer:1,explanation:'Add .github/workflows/dependency-review.yml using actions/dependency-review-action. It compares package-lock.json, pom.xml, etc. between the base and PR branch and fails if new high/critical CVEs are introduced.'},
{id:3483,topic:'git-github',difficulty:'intermediate',question:'What is the `GITHUB_TOKEN` secret in GitHub Actions?',options:['A personal access token','An automatically provisioned, short-lived token scoped to the current repository, created fresh for each workflow run and expired when it ends','A permanent service account token','An OAuth token'],answer:1,explanation:'GITHUB_TOKEN is auto-created by GitHub at workflow start with configurable permissions. Default permissions are configurable at org/repo level. Scope: contents:read, pull-requests:write, etc. Never stored; always fresh.'},
{id:3484,topic:'git-github',difficulty:'intermediate',question:'How do you restrict `GITHUB_TOKEN` permissions in a workflow?',options:['It cannot be restricted','Set permissions at workflow or job level: permissions: contents: read; pull-requests: write. This grants least-privilege access, reducing blast radius if a step is compromised.','Use a repo setting only','Use environment variables'],answer:1,explanation:'permissions: block sets minimal scopes: contents: read prevents write access. Set at top-level (all jobs) or per-job for fine-grained control. Read-only fork PRs automatically get restricted permissions.'},
{id:3485,topic:'git-github',difficulty:'intermediate',question:'What is `actions/checkout` and why is `fetch-depth: 0` important?',options:['Downloads all GitHub Actions','Checks out the repository; by default only fetches a shallow clone (depth 1). fetch-depth: 0 fetches full history, required for git log, version tagging, and conventional-commits based versioning tools.','Sets checkout permissions','Caches the repository'],answer:1,explanation:'Default actions/checkout is a shallow clone (--depth=1). For semantic-release, standard-version, or git log based tools: with: fetch-depth: 0. For PRs: also fetch the base branch for diff comparison.'},
{id:3486,topic:'git-github',difficulty:'intermediate',question:'What is `concurrency` in GitHub Actions?',options:['Parallel job limit','A workflow/job setting that cancels or queues concurrent runs with the same group key: concurrency: group: ${{github.workflow}}-${{github.ref}}; cancel-in-progress: true','A thread pool setting','A runner concurrency limit'],answer:1,explanation:'concurrency: group: ensures only one run per branch/PR at a time. cancel-in-progress: true cancels the old run when a new commit is pushed. Prevents wasted CI minutes on superseded builds.'},
{id:3487,topic:'git-github',difficulty:'intermediate',question:'What is `if:` conditional in GitHub Actions?',options:['An if-else statement','An expression evaluated before running a job or step; if false, the job/step is skipped: if: github.ref == "refs/heads/main" || github.event_name == "release"','A YAML anchor','A loop condition'],answer:1,explanation:'if: conditions use GitHub Actions expression syntax: ${{...}} or bare expressions. Common patterns: if: github.event_name != "pull_request" (skip on PRs), if: failure() (run cleanup on failure), if: always() (run regardless of prior steps).'},
{id:3488,topic:'git-github',difficulty:'intermediate',question:'What is `needs:` in GitHub Actions jobs?',options:['A dependency declaration for packages','Specifies that a job should only start after the listed jobs complete successfully, creating a job dependency graph for ordered execution','A conditional trigger','A job group'],answer:1,explanation:'jobs: deploy: needs: [test, build]. The deploy job waits for test AND build to succeed. If either fails, deploy is skipped. needs also makes outputs from previous jobs available.'},
{id:3489,topic:'git-github',difficulty:'intermediate',question:'What are GitHub Actions job outputs?',options:['Console output only','Values set in one job via GITHUB_OUTPUT and consumed by dependent jobs via needs.job-id.outputs.key, enabling data passing between jobs','Environment variables shared across jobs','Artifacts automatically'],answer:1,explanation:'Set: echo "version=1.2.3" >> $GITHUB_OUTPUT in a step. Reference in a dependent job: ${{needs.build.outputs.version}}. Outputs are strings. For complex data, use artifacts.'},
{id:3490,topic:'git-github',difficulty:'advanced',question:'What is an OpenID Connect (OIDC) token in GitHub Actions?',options:['A login token','A short-lived JWT token issued by GitHub\'s OIDC provider that allows GitHub Actions workflows to authenticate to cloud providers (AWS, Azure, GCP) without storing long-lived secrets','A GitHub App token','An OAuth 2.0 access token'],answer:1,explanation:'OIDC eliminates long-lived cloud credentials in secrets. Configure cloud provider to trust GitHub\'s OIDC issuer. GitHub mints a JWT per job. Cloud IAM policy matches the token\'s subject (repo + environment). No secrets needed.'},
{id:3491,topic:'git-github',difficulty:'advanced',question:'What is the benefit of OIDC over secrets for cloud deployments?',options:['No benefit — secrets are simpler','OIDC tokens are short-lived (expire with the job), cannot be leaked via secret exposure, and enforce the exact repo/branch/environment in the trust policy, significantly reducing cloud credential risk','OIDC is faster','OIDC works offline'],answer:1,explanation:'With OIDC: no long-lived AWS_ACCESS_KEY_ID stored in GitHub. The token is valid only during the job. The IAM policy can restrict to main branch or production environment. Rotation is automatic.'},
{id:3492,topic:'git-github',difficulty:'intermediate',question:'What is `git log --graph --oneline --decorate`?',options:['Shows a tree of files','Displays a compact ASCII art representation of the commit graph with branch/tag names (decorations) and one-line commit summaries','Generates a DOT file','Opens a GUI'],answer:1,explanation:'The combination is the most popular "pretty" log alias: graph draws branch lines, oneline compresses each commit to one line (short hash + message), decorate shows branch/tag references. Often aliased as git lg.'},
{id:3493,topic:'git-github',difficulty:'intermediate',question:'What is `git log --author="Name" --since="2 weeks ago"`?',options:['Shows all commits','Filters log to show only commits by the specified author within the last 2 weeks. --until, --after, --before also filter by date.','Opens an interactive log','Shows diff statistics'],answer:1,explanation:'git log supports: --author (regex match on author name/email), --since/--after (inclusive start date), --until/--before (exclusive end date), --grep (message filter), --all (all branches). Combine freely.'},
{id:3494,topic:'git-github',difficulty:'intermediate',question:'What is `git shortlog -sn`?',options:['A short log format','Shows a sorted summary of commits per author: -s (suppress individual commit messages, show count), -n (sort by number of commits descending). Great for contribution statistics.','A short commit hash listing','Counts files changed'],answer:1,explanation:'git shortlog -sn outputs: 342 Alice, 215 Bob, 89 Charlie — sorted by commit count. git shortlog -sne also shows email. Useful for CONTRIBUTORS files and contribution reporting.'},
{id:3495,topic:'git-github',difficulty:'intermediate',question:'What does `git describe` do?',options:['Describes a file','Produces a human-readable version string based on the nearest tag, commit count since tag, and short hash: v1.2.0-14-g8d3f1a2','Describes the repository','Lists tags'],answer:1,explanation:'git describe --tags finds the nearest annotated tag and appends -N-gSHA. Use --always to fall back to SHA if no tags. Useful for build version strings: VERSION=$(git describe --tags --always --dirty).'},
{id:3496,topic:'git-github',difficulty:'intermediate',question:'What is `git notes`?',options:['A comment system','Attaches extra metadata (notes) to commits without changing the commit hash — notes are stored in a separate refs/notes namespace','A documentation feature','An annotation system for files'],answer:1,explanation:'git notes add -m "Deploy date: 2024-01-15" HEAD attaches a note. git log shows notes inline. Notes are not pushed by default: git push origin refs/notes/commits. Used for CI metadata, deploy info, and annotations.'},
{id:3497,topic:'git-github',difficulty:'advanced',question:'What is `git replace`?',options:['Replaces file content','Creates a replacement for an object (commit, tree, blob) allowing you to edit history appearance without changing commit hashes — used for graft points and history cleanup','Replaces a branch reference','An alias for git checkout'],answer:1,explanation:'git replace <old> <new> makes Git transparently substitute <new> when <old> is referenced. Used to join disconnected history (grafts) or replace a malformed commit without rewriting all descendants.'},
{id:3498,topic:'git-github',difficulty:'advanced',question:'What is `git filter-repo`?',options:['Filters log output','The recommended tool for rewriting repository history: removing large files, changing author emails, splitting repos, subdirectory extraction — faster and safer than git filter-branch','A log filter command','A commit message editor'],answer:1,explanation:'git filter-repo --path src --path-rename src:root extracts the src directory to repo root. --invert-paths removes files. --email-callback for author rewrites. Much faster than deprecated git filter-branch.'},
{id:3499,topic:'git-github',difficulty:'advanced',question:'What is a BFG Repo Cleaner?',options:['A file renaming tool','A faster alternative to git filter-branch for removing large files or sensitive data from Git history: bfg --strip-blobs-bigger-than 50M','A branch manager','A fork cleanup tool'],answer:1,explanation:'BFG removes large files (--strip-blobs-bigger-than 100M) or sensitive data (--replace-text passwords.txt) faster than filter-branch. After BFG: git reflog expire --expire=now --all; git gc --prune=now --aggressive.'},
{id:3500,topic:'git-github',difficulty:'intermediate',question:'What is `git worktree add` used for?',options:['Adds files to staging','Creates an additional working tree linked to the same repository, allowing simultaneous checkout of multiple branches without cloning twice','Creates a new repository','Adds a remote repository'],answer:1,explanation:'git worktree add ../hotfix hotfix-branch creates a second working directory at ../hotfix checked out on the hotfix-branch. Both share the same .git. Useful for parallel work without switching branches.'},
{id:3501,topic:'git-github',difficulty:'intermediate',question:'What is the `git stash` list format?',options:['Numbered list only','stash@{0}: WIP on main: a1b2c3d commit message — shows index, branch name, and tip commit when stashed','A description only','The file list changed'],answer:1,explanation:'git stash list shows: stash@{0}: WIP on feature: abc123 Add login; stash@{1}: On main: def456 Fix typo. Reference specific stash: git stash pop stash@{2}. git stash show -p shows the diff.'},
{id:3502,topic:'git-github',difficulty:'intermediate',question:'What is `git stash branch <branchname>`?',options:['Creates a branch from a stash','Creates a new branch from the commit where the stash was created, then applies the stash to it — avoids conflicts when the stash conflicts with current branch','Stashes the current branch','Merges the stash into a branch'],answer:1,explanation:'git stash branch feature-wip is the clean way to convert a stash into a feature branch. It checks out the original commit, applies the stash, and drops it. Conflict-free because you are on the original commit.'},
{id:3503,topic:'git-github',difficulty:'intermediate',question:'What does `git pull --rebase` do vs `git pull`?',options:['They are identical','--rebase: fetches and replays local commits on top of the upstream commits (linear history). Default pull: fetches and creates a merge commit (non-linear). --rebase is preferred for cleaner history.','--rebase discards local commits','--rebase creates a new branch'],answer:1,explanation:'git config --global pull.rebase true sets rebase as default. Avoids messy "Merge remote-tracking branch" commits in history. If conflicts occur during rebase: git rebase --abort to cancel.'},
{id:3504,topic:'git-github',difficulty:'intermediate',question:'What is `git push --force-with-lease` vs `--force`?',options:['They are identical','--force-with-lease is safer: it only force-pushes if no one else has pushed since your last fetch, preventing you from overwriting others\' work. --force always overwrites regardless.','--force-with-lease is slower','--force-with-lease requires authentication'],answer:1,explanation:'Always prefer --force-with-lease over --force when force-pushing. If a colleague pushed while you were rebasing, --force-with-lease fails with "rejected" — --force would have silently deleted their commits.'},
{id:3505,topic:'git-github',difficulty:'intermediate',question:'What is `git fetch --prune`?',options:['Deletes local branches','Fetches from remote and removes local remote-tracking references (origin/deleted-branch) that no longer exist on the remote','Deletes all tags','Cleans the repository'],answer:1,explanation:'After remote branches are deleted, git fetch --prune removes stale remote-tracking refs. git remote prune origin does the same without fetching. Configure permanently: git config --global fetch.prune true.'},
{id:3506,topic:'git-github',difficulty:'intermediate',question:'What does `git clean -fdx` do?',options:['Fixes broken files','Removes all untracked files (-f force), directories (-d), and gitignored files (-x) from the working tree. Extremely destructive — cannot be undone.','Fixes line endings','Clears the stash'],answer:1,explanation:'git clean -fd: removes untracked files and directories. -x: also removes ignored files (.DS_Store, __pycache__, node_modules). -n (dry run) shows what would be deleted. Use -n first to preview!'},
{id:3507,topic:'git-github',difficulty:'beginner',question:'What is a `.gitattributes` file used for?',options:['Git user settings','Configures per-path attributes: line-ending normalization (text=auto, eol=lf/crlf), diff drivers, merge strategies, and linguist overrides for language detection','A branch protection file','A hook configuration'],answer:1,explanation:'.gitattributes: * text=auto (normalize line endings), *.sh eol=lf, *.bat eol=crlf, *.jpg binary, *.pbxproj merge=union. Stored in the repo, affects all contributors consistently.'},
{id:3508,topic:'git-github',difficulty:'beginner',question:'What is `git log --stat`?',options:['Shows statistics only','Shows each commit with a summary of which files were changed and how many lines were inserted/deleted (insertions(+)/deletions(-) per file)','Shows commit count','Shows author statistics'],answer:1,explanation:'git log --stat shows per-commit file change stats: src/app.js | 15 +++++++------- This helps understand the scope of each commit at a glance. --numstat gives machine-readable numbers.'},
{id:3509,topic:'git-github',difficulty:'intermediate',question:'What is `git diff HEAD~1`?',options:['Shows pending changes','Shows the difference between the working tree and the commit one before HEAD (or between any two commits/refs). Useful to review the last commit\'s changes.','Shows staged changes only','Shows branch differences'],answer:1,explanation:'git diff HEAD~1 shows working tree vs 1 commit ago. git diff HEAD~1 HEAD shows the last commit\'s diff. git diff main..feature shows diff between branches. git diff --cached shows staged changes.'},
{id:3510,topic:'git-github',difficulty:'intermediate',question:'What is `git show HEAD~3:path/to/file`?',options:['Checks out the file','Displays the content of a specific file as it was 3 commits ago — useful for comparing file content across commits without switching branches','Restores the file','Deletes the file'],answer:1,explanation:'git show COMMIT:PATH outputs the file content at that commit. git show HEAD~3:src/config.js shows config 3 commits ago. Use git checkout COMMIT -- PATH to restore it to the working tree.'},
{id:3511,topic:'git-github',difficulty:'intermediate',question:'What is `git rev-parse HEAD`?',options:['Reverses a commit','Resolves a ref to its full 40-character SHA-1 hash. git rev-parse --abbrev-ref HEAD shows the current branch name.','Parses the repository','Shows the reflog'],answer:1,explanation:'git rev-parse HEAD outputs the full SHA: a1b2c3d.... git rev-parse --short HEAD gives short SHA. git rev-parse --abbrev-ref HEAD gives branch name (main). Useful in scripts and CI/CD pipelines.'},
{id:3512,topic:'git-github',difficulty:'intermediate',question:'What is `git archive` used for?',options:['Archives the repository permanently','Creates a tar or zip archive of a tree/commit for distribution — does not include the .git directory. Useful for creating release artifacts.','Compresses the git objects','Creates a backup of .git'],answer:1,explanation:'git archive --format=tar.gz HEAD > release.tar.gz creates a clean archive without .git. git archive v1.2.0 --prefix=myapp-1.2.0/ | gzip > release.tar.gz creates a prefixed archive from a tag.'},
{id:3513,topic:'git-github',difficulty:'advanced',question:'What is `git bundle` used for?',options:['Packages npm bundles','Creates a binary file containing a complete or partial git repository that can be transferred offline and cloned/fetched from, useful for air-gapped environments','Bundles multiple repos','A compression format'],answer:1,explanation:'git bundle create repo.bundle HEAD main creates a portable repo. git clone repo.bundle myrepo or git fetch ../repo.bundle main. Useful for air-gapped deployments, emailing repo history, or CI artifact transfer.'},
{id:3514,topic:'git-github',difficulty:'intermediate',question:'What is `git bisect run` automated bisection?',options:['Runs all tests automatically','Runs a script for each bisect step: exit 0 = good, exit 1 = bad (non-0, non-125). Git automatically narrows the regression to the offending commit in O(log n) steps.','Bisects the git log','Runs a CI pipeline'],answer:1,explanation:'git bisect start; git bisect bad HEAD; git bisect good v1.0; git bisect run ./test.sh. Git checks out commits, runs test.sh, and uses exit codes to binary-search for the regression commit automatically.'},
{id:3515,topic:'git-github',difficulty:'intermediate',question:'What is `git cherry-pick --no-commit`?',options:['Cancels cherry-pick','Applies the changes from the specified commit to the working tree and staging area but does not create a commit, allowing you to combine multiple cherry-picks before committing','Merges without committing','Stages changes only'],answer:1,explanation:'git cherry-pick --no-commit abc123 def456 applies both commits\' changes without committing. You can then review, add more changes, and commit once with a single consolidated commit.'},
{id:3516,topic:'git-github',difficulty:'beginner',question:'What does `git remote -v` show?',options:['Remote server status','Lists all configured remote repositories with their fetch and push URLs, showing both the remote name (e.g., origin) and the URL','Remote branch list','Remote commit history'],answer:1,explanation:'git remote -v: origin  https://github.com/user/repo.git (fetch); origin  https://github.com/user/repo.git (push). Shows both URLs (they can differ, e.g., fetch via HTTPS, push via SSH).'},
{id:3517,topic:'git-github',difficulty:'beginner',question:'What is `origin` in Git?',options:['The main branch','The conventional name for the default remote repository (the one you cloned from). You can rename it or add additional remotes.','The first commit','The repository root'],answer:1,explanation:'When you git clone, the source is named "origin" by default. git remote add upstream URL adds a second remote (common in fork workflows). git fetch origin downloads changes from origin.'},
{id:3518,topic:'git-github',difficulty:'intermediate',question:'What is upstream vs origin in a fork workflow?',options:['They are the same','Origin: your personal fork. Upstream: the original repository you forked from. git fetch upstream; git merge upstream/main keeps your fork in sync with the original project.','Upstream is deprecated','Origin is the original repo'],answer:1,explanation:'Fork workflow: fork on GitHub (your copy = origin), clone your fork, add original as upstream. Sync: git fetch upstream; git checkout main; git merge upstream/main; git push origin main.'},
{id:3519,topic:'git-github',difficulty:'intermediate',question:'What is `git config --global core.autocrlf`?',options:['Converts all files','Controls line-ending conversion: true (Windows: check in LF, check out CRLF), input (Mac/Linux: normalize to LF on check in), false (no conversion). Prevents line-ending conflicts.','A whitespace setting','An editor setting'],answer:1,explanation:'Windows: core.autocrlf=true. Linux/Mac: core.autocrlf=input. This ensures the repo stores LF line endings while Windows developers get CRLF locally. .gitattributes is a more reliable team-wide solution.'},
{id:3520,topic:'git-github',difficulty:'intermediate',question:'What is `git config --global core.editor`?',options:['Sets the file viewer','Sets the default text editor used for commit messages, rebase todo lists, and other interactive git prompts. Example: git config --global core.editor "code --wait"','Sets the diff tool','Sets the merge tool'],answer:1,explanation:'Set VS Code: core.editor = "code --wait". Vim: "vim". Nano: "nano". The --wait flag is critical for VS Code/Sublime so git waits for the editor to close before continuing.'},
{id:3521,topic:'git-github',difficulty:'beginner',question:'What does `git init --bare` create?',options:['A repository with no commits','A repository without a working directory, containing only the git objects and refs — used as a shared central repository (like GitHub) that only accepts push/fetch, not direct editing','An empty repository','A mirror repository'],answer:1,explanation:'Bare repos have no working tree: just the .git directory contents. Used as central servers: git init --bare repo.git. GitHub stores repos as bare repositories. You cannot commit directly in a bare repo.'},
{id:3522,topic:'git-github',difficulty:'intermediate',question:'What is `git log --follow`?',options:['Follows a branch','Continues tracking a file\'s history across renames: git log --follow -- path/to/file shows the complete history even if the file was moved or renamed','Follows a user','Follows merge commits'],answer:1,explanation:'Without --follow, git log -- file stops at the rename. With --follow, it detects renames (via similarity index) and shows the complete history across all names. Essential for understanding a file\'s full evolution.'},
{id:3523,topic:'git-github',difficulty:'intermediate',question:'What is `git reflog expire --expire=now --all` used for?',options:['Backs up the reflog','Immediately expires all reflog entries, making previously reachable objects eligible for garbage collection. Used before git gc --prune=now to fully clean up history rewrite operations.','Resets the branch','Deletes remote refs'],answer:1,explanation:'After history rewrites (filter-repo, BFG): expire reflog then gc to actually free disk space. git reflog expire --expire=now --all; git gc --prune=now --aggressive. Without this, old objects persist for 90 days (default reflog expiry).'},
{id:3524,topic:'git-github',difficulty:'intermediate',question:'What is the GitHub Actions `GITHUB_OUTPUT` environment file?',options:['A log file','The mechanism for setting step outputs in modern GitHub Actions: echo "name=value" >> $GITHUB_OUTPUT (replacing deprecated ::set-output:: commands)','A workflow output file','An artifact file'],answer:1,explanation:'Since June 2023, use: echo "version=$VERSION" >> $GITHUB_OUTPUT instead of deprecated ::set-output::version=$VERSION::. GITHUB_OUTPUT is a temp file path. Steps outputs are read with ${{steps.step-id.outputs.name}}.'},
{id:3525,topic:'git-github',difficulty:'intermediate',question:'What is the difference between `GITHUB_ENV` and `GITHUB_OUTPUT`?',options:['They are identical','GITHUB_ENV sets environment variables available to all subsequent steps in the same job; GITHUB_OUTPUT sets step outputs available to subsequent steps and dependent jobs','GITHUB_ENV is deprecated','GITHUB_OUTPUT is for artifacts'],answer:1,explanation:'echo "MY_VAR=value" >> $GITHUB_ENV makes MY_VAR available in all subsequent steps. echo "result=value" >> $GITHUB_OUTPUT makes it available via ${{steps.this-step.outputs.result}} in subsequent steps and via needs.job.outputs in dependent jobs.'},
{id:3526,topic:'git-github',difficulty:'intermediate',question:'What is `actions/upload-artifact` used for?',options:['Uploads to cloud storage','Persists files from a job (build outputs, test results, coverage reports) so they can be downloaded by humans or by subsequent jobs using actions/download-artifact','Caches dependencies','Uploads to GitHub Releases'],answer:1,explanation:'Use: actions/upload-artifact@v4 with: name: build-output, path: dist/. Download in another job: actions/download-artifact@v4 with: name: build-output. Artifacts persist for retention-days (default 90 days).'},
{id:3527,topic:'git-github',difficulty:'intermediate',question:'What is `actions/cache` used for?',options:['Caches Docker images','Caches dependencies between workflow runs to speed up jobs: key identifies the cache, path specifies what to cache. Restores on cache hit, saves on miss.','Stores build artifacts','Caches secrets'],answer:1,explanation:'actions/cache@v4: key: ${{runner.os}}-node-${{hashFiles("**/package-lock.json")}}, path: ~/.npm. On cache hit, restores instantly. On miss, job runs and saves the cache. Dramatically reduces install times.'},
{id:3528,topic:'git-github',difficulty:'intermediate',question:'What is a self-hosted GitHub Actions runner?',options:['A local GitHub server','A machine (physical, VM, or container) you provide that registers with GitHub and executes Actions workflows, giving control over hardware, software, and network','A paid runner option','A runner in GitHub\'s cloud'],answer:1,explanation:'Register: ./config.sh --url https://github.com/org/repo --token TOKEN. Self-hosted runners access private networks, use custom hardware (GPU, ARM), and avoid GitHub-hosted runner minutes. Can be ephemeral (one job then terminate) for security.'},
{id:3529,topic:'git-github',difficulty:'advanced',question:'What are ephemeral (just-in-time) self-hosted runners?',options:['Temporary GitHub-hosted runners','Runners provisioned per-job and terminated after one job completes, preventing job contamination and providing a clean environment each time. Use --ephemeral flag in runner config.','Runners without a configuration','Prewarmed runners'],answer:1,explanation:'--ephemeral flag: runner exits after one job. Prevents one job\'s artifacts/processes from affecting the next. Use with an autoscaler (actions-runner-controller for Kubernetes, AWS EC2 with Lambda provisioning).'},
{id:3530,topic:'git-github',difficulty:'intermediate',question:'What is `actions-runner-controller` (ARC)?',options:['A GitHub Actions plugin','A Kubernetes operator that automatically scales self-hosted GitHub Actions runners based on workflow demand, running ephemeral runners as Kubernetes pods','A runner management GUI','An Actions SDK'],answer:1,explanation:'ARC watches GitHub Actions queue and scales runner pods up/down. RunnerDeployment (static pool) or RunnerSet with autoscaling. Runners are ephemeral Kubernetes pods, terminated after each job. Dramatically reduces cloud costs vs always-on runners.'},
{id:3531,topic:'git-github',difficulty:'beginner',question:'What is a GitHub Codespace?',options:['A GitHub code editor only','A cloud-based development environment (VSCode in the browser or connected to local VSCode) with a pre-configured devcontainer, providing instant access to any repo without local setup','A virtual machine service','A code review tool'],answer:1,explanation:'Codespaces launch a container (devcontainer.json defines the environment) with VS Code. Pre-builds cache common operations for faster startup. Billed per CPU-hours. Supports 2, 4, 8, 16, 32 CPU options.'},
{id:3532,topic:'git-github',difficulty:'intermediate',question:'What is `devcontainer.json`?',options:['A Dockerfile alternative','A configuration file (in .devcontainer/ or .devcontainer.json) defining the development container environment: image, Dockerfile, features, VS Code extensions, port forwards, and post-create commands','A GitHub environment config','A deployment container spec'],answer:1,explanation:'devcontainer.json: { "image": "mcr.microsoft.com/devcontainers/node:20", "features": {...}, "extensions": [...], "postCreateCommand": "npm install", "forwardPorts": [3000] }. Used by Codespaces and VS Code Dev Containers.'},
{id:3533,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub repository template?',options:['A README template','A repository marked as a template that others can use to create new repositories with the same directory structure, files, and (optionally) Actions workflows, without the full git history','A branch template','A PR template'],answer:1,explanation:'Settings > Template repository checkbox. When creating a new repo, choose "from template". Creates a fresh repo (not a fork) with the template\'s files. Great for project scaffolding and standards enforcement.'},
{id:3534,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub release and how does it relate to tags?',options:['A deployment notification','A GitHub-specific construct built on a git tag that adds release notes, binaries (uploaded assets), and a changelog. Releases are human-facing; tags are git-native.','A CI/CD deployment','A branch snapshot'],answer:1,explanation:'Create release: gh release create v1.2.0 dist/*.tar.gz --notes "Changelog here". GitHub Release = tag + release notes + uploaded assets. on: release: types: [published] triggers CI workflows for release deployments.'},
{id:3535,topic:'git-github',difficulty:'intermediate',question:'What is `semantic-release` in the context of GitHub?',options:['A version bump script','A fully automated versioning and release tool that determines version bumps from conventional commits, updates CHANGELOG, creates git tags, and publishes packages','A semantic git command','A GitHub Action'],answer:1,explanation:'semantic-release reads conventional commits since last release: fix → patch, feat → minor, BREAKING CHANGE → major. Runs in CI: creates GitHub Release, publishes to npm, updates CHANGELOG.md automatically. Zero manual versioning.'},
{id:3536,topic:'git-github',difficulty:'intermediate',question:'What is GitHub\'s squash and merge button vs create a merge commit vs rebase and merge?',options:['They are identical','Squash: combines all PR commits into one commit on base branch. Merge commit: preserves all commits plus adds a merge commit. Rebase: replays each PR commit onto base branch linearly. Different history strategies.','All create merge commits','Squash is the only option'],answer:1,explanation:'Squash merge: clean history, one commit per feature. Merge commit: full history preserved, PR clearly visible. Rebase: linear history without merge commits, preserves individual commits. Team should agree on one strategy for consistency.'},
{id:3537,topic:'git-github',difficulty:'intermediate',question:'What is branch auto-deletion after merge in GitHub?',options:['A dangerous setting','A repository setting (Automatically delete head branches) that deletes the feature branch after a PR is merged, keeping the branch list clean. Branches can be restored from closed PRs.','A force delete setting','A commit deletion feature'],answer:1,explanation:'Settings > Automatically delete head branches. After merge, the feature branch is deleted. The PR preserves the branch\'s commit history. Restore: on the closed PR page, click "Restore branch". Good hygiene for active repos.'},
{id:3538,topic:'git-github',difficulty:'intermediate',question:'What is `git config --global alias`?',options:['Creates a shell alias','Creates a Git command shortcut: git config --global alias.lg "log --graph --oneline --decorate --all" creates "git lg"','Creates a function','An alias for a remote'],answer:1,explanation:'Common aliases: alias.st = status, alias.co = checkout, alias.br = branch, alias.cm = "commit -m", alias.unstage = "reset HEAD --". Stored in ~/.gitconfig under [alias] section.'},
{id:3539,topic:'git-github',difficulty:'intermediate',question:'What is `git commit --fixup` and `--autosquash`?',options:['Fixes merge conflicts','--fixup=COMMIT creates a commit prefixed "fixup!" that --autosquash in interactive rebase automatically moves and squashes with the target commit. Clean way to amend old commits.','An automatic fix tool','A rebase conflict resolver'],answer:1,explanation:'git commit --fixup=abc123 creates: "fixup! Original commit message". git rebase -i --autosquash HEAD~10 auto-arranges fixup commits under their targets. Keeps fixup commits out of main history.'},
{id:3540,topic:'git-github',difficulty:'beginner',question:'What is `git status --short`?',options:['A brief summary of HEAD','Shows a compact two-column status: M (modified), A (added), D (deleted), ? (untracked), R (renamed). Left column = staged, right = working tree. More concise than default output.','Shows file sizes','Shows branch status only'],answer:1,explanation:'git status -s (short): M  file.js (staged modified), MM file2.js (staged and unstaged modified), ?? new-file.txt (untracked), A  new.js (staged new file). Faster to read than verbose status.'},
{id:3541,topic:'git-github',difficulty:'intermediate',question:'What is a shallow clone and when to use it?',options:['A clone without branches','A clone with limited history depth: git clone --depth=1 URL fetches only the most recent commit per branch. Faster for CI/CD where full history is not needed.','A clone without tags','A partial file clone'],answer:1,explanation:'--depth=1: only latest commit, no history. --depth=50: last 50 commits. Excellent for CI pipelines where you only need to build/test the current code. Cannot do git log, git blame, or bisect on shallow clones.'},
{id:3542,topic:'git-github',difficulty:'intermediate',question:'What is `git unshallow`?',options:['Deletes a shallow clone','Converts a shallow clone to a full clone: git fetch --unshallow. Fetches all missing history. Needed when switching from CI-style clones to developer workflows requiring full history.','Creates a shallow copy','A clone depth increase command'],answer:1,explanation:'git fetch --unshallow makes a shallow clone into a full clone by fetching all omitted history. git clone --filter=blob:none is often better than shallow for large repos as it is smarter about what to fetch.'},
{id:3543,topic:'git-github',difficulty:'advanced',question:'What is the Git object model (blob, tree, commit, tag)?',options:['Git database tables','Four object types: blob (file content), tree (directory listing of blobs and trees), commit (snapshot with metadata and parent pointers), annotated tag (points to another object with metadata)','Git ref types','Git file types'],answer:1,explanation:'All Git content is addressed by SHA-1/SHA-256 hash. Blobs: file contents. Trees: directories containing blobs and trees. Commits: tree hash + parent(s) + author/committer/message. Tags: annotated pointer with message. Everything is content-addressed.'},
{id:3544,topic:'git-github',difficulty:'advanced',question:'What is a pack file in Git?',options:['A zip archive of commits','A binary file storing multiple git objects in compressed delta-encoded format, dramatically reducing disk space versus storing objects individually (loose objects)','An archive format','A bundle format'],answer:1,explanation:'Git packs loose objects into .pack files (with .idx index). Uses delta compression between similar objects. git gc triggers repacking. git repack -adf creates an optimal single pack. Large repos benefit enormously from good pack organization.'},
{id:3545,topic:'git-github',difficulty:'advanced',question:'What is the difference between SHA-1 and SHA-256 in Git?',options:['SHA-256 is deprecated','Git historically used SHA-1 for object hashing. SHA-256 (git 2.29+) is a new hash algorithm transition providing cryptographic security against SHA-1 collision attacks (SHAttered). Opt-in with --object-format=sha256.','They are interchangeable','SHA-256 is for tags only'],answer:1,explanation:'SHA-1 is still the default for compatibility. SHA-256 repos (--object-format=sha256) produce 64-char hashes. Migration from SHA-1 to SHA-256 repos requires transition support. GitHub is actively working on SHA-256 support.'},
{id:3546,topic:'git-github',difficulty:'intermediate',question:'What is `git gc --aggressive`?',options:['Deletes all garbage','Runs a more thorough garbage collection with higher compression settings and more aggressive delta optimization. Takes much longer but produces smaller pack files.','Removes all unreachable commits','Forces garbage collection immediately'],answer:1,explanation:'git gc (default): quick optimization. git gc --aggressive: thorough repacking with -f (force) and higher window/depth for delta compression. Best used occasionally (after large history rewrites) not regularly, as it can worsen performance.'},
{id:3547,topic:'git-github',difficulty:'intermediate',question:'What is `git fsck`?',options:['File system check','Verifies the integrity of the git object database: checks for missing objects, broken links, dangling commits/blobs, and corrupt pack files','A file permission check','A repository validator'],answer:1,explanation:'git fsck reports dangling (unreachable but present) and missing objects. git fsck --lost-found writes lost objects to .git/lost-found/. Useful for recovering lost commits or debugging repository corruption.'},
{id:3548,topic:'git-github',difficulty:'beginner',question:'What is a GitHub PR template?',options:['A branch template','A file (.github/pull_request_template.md) that pre-fills the PR description for all new pull requests in a repository, ensuring contributors provide required information like checklist, testing steps, and issue links','A commit message template','A workflow template'],answer:1,explanation:'.github/pull_request_template.md: ## Changes, ## Testing, ## Checklist: - [ ] Tests added. Automatically populates the PR body when a contributor opens a new PR. Multiple templates: .github/PULL_REQUEST_TEMPLATE/ directory.'},
{id:3549,topic:'git-github',difficulty:'beginner',question:'What is a GitHub Issue template?',options:['A report format','Files in .github/ISSUE_TEMPLATE/ (or YAML config) that present structured forms when opening issues, prompting for specific information like bug reports or feature requests','A PR template','A discussion template'],answer:1,explanation:'ISSUE_TEMPLATE: bug_report.md, feature_request.md. YAML forms (.github/ISSUE_TEMPLATE/config.yml) provide structured dropdowns and checkboxes. Reduces incomplete bug reports and improves issue quality.'},
{id:3550,topic:'git-github',difficulty:'intermediate',question:'What is a GitHub Actions workflow trigger `workflow_dispatch`?',options:['Triggers on code push','Allows manual triggering of a workflow from the GitHub UI or CLI, optionally accepting typed inputs (string, boolean, choice, number, environment) provided at trigger time','Triggers on pull requests','Triggers on schedule'],answer:1,explanation:'on: workflow_dispatch: inputs: environment: type: choice, options: [staging, production]. Trigger via UI (Actions tab > workflow > Run workflow) or CLI: gh workflow run deploy.yml --field environment=staging.'}
]);
